'use strict';
// Offline review probes: pinned source is compiled in memory; generated bytes are captured.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const {execFileSync} = require('node:child_process');
const {createRequire, Module} = require('node:module');
const portalRoot = path.resolve(__dirname, '../../../../..');
const wsuRoot = '/home/andrew/src/bitbucket/redbox-hook-wsu-v6';
const portalRequire = createRequire(path.join(portalRoot, 'package.json'));
const wsuRequire = createRequire(path.join(wsuRoot, 'package.json'));
const ts = portalRequire('typescript');
const current = '8dd61118eed9582be8d4d01359677b9be4dba631';
const baseline = '14ab99eb3a89434b9c886d51d5edc37447f43588';
const source = (ref, file) => execFileSync('git', ['show', `${ref}:${file}`], {cwd: wsuRoot, encoding: 'utf8'});
function compile(ref, file, overrides = {}, cache = new Map()) {
  if (cache.has(file)) return cache.get(file).exports;
  const filename = path.join(wsuRoot, file);
  const module = new Module(filename);
  cache.set(file, module);
  module.filename = filename;
  module.paths = Module._nodeModulePaths(path.dirname(filename));
  module.require = name => {
    if (Object.hasOwn(overrides, name)) return overrides[name];
    if (name.startsWith('.')) {
      const child = path.relative(wsuRoot, path.resolve(path.dirname(filename), name)) + '.ts';
      return compile(ref, child, overrides, cache);
    }
    return wsuRequire(name);
  };
  module._compile(ts.transpileModule(source(ref, file), {compilerOptions: {
    module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022, esModuleInterop: true,
  }}).outputText, filename);
  return module.exports;
}
(async () => {
  const jsonata=portalRequire('jsonata');
  const keys=['REDBOX_PUBLIC_URL','SAILS_APP_URL','sails_appUrl','DOI_PUBLIC_LANDING_URL','DOI_INSTRUMENT_LANDING_URL','SAILS_DOI__PUBLICLANDINGURL','SAILS_DOI__INSTRUMENTLANDINGURL'];
  const saved=Object.fromEntries(keys.map(k=>[k,process.env[k]]));
  const results=[];
  try {
    for(const [label,ref,ambient] of [['baseline',baseline,'SAILS_APP_URL'],['incoming',current,'REDBOX_PUBLIC_URL']]) {
      for(const row of [
        {name:'selected-file-url-only',public:'https://research-data.westernsydney.edu.au/published/abc',instrument:'https://research-data.westernsydney.edu.au/default/rdmp/record/view/abc'},
        {name:'ambient-url-custom-brand',env:true,public:'https://institution.example.invalid/research/published/abc',instrument:'https://institution.example.invalid/research/default/rdmp/record/view/abc'},
        {name:'explicit-doi-bases',explicit:true,public:'https://public.example.invalid/pages/abc',instrument:'https://institution.example.invalid/research/institution/research/record/view/abc'},
      ]) {
        keys.forEach(k=>delete process.env[k]);
        if(row.env)process.env[ambient]='https://institution.example.invalid/research';
        if(row.explicit) {
          process.env.DOI_PUBLIC_LANDING_URL='https://public.example.invalid/pages/';
          process.env.DOI_INSTRUMENT_LANDING_URL='https://institution.example.invalid/research/institution/research/record/view/';
        }
        const helpers=compile(ref,'src/config/doiPublishing.ts');
        const evaluate=expression=>jsonata(expression).evaluate({record:{metadata:{}},oid:'abc'});
        const actual={public:await evaluate(helpers.publicLandingUrlExpression()),instrument:await evaluate(helpers.instrumentLandingUrlExpression())};
        assert.equal(actual.public,row.public);assert.equal(actual.instrument,row.instrument);
        results.push({source:label,revision:ref,case:row.name,selectedServerPublicUrl:'https://institution.example.invalid/research',selectedBrand:'institution',selectedPortal:'research',...actual,disposition:row.explicit?'explicit workaround accepted':'inherited P2: ambient-only URL/default brand derivation'});
      }
    }
  } finally {keys.forEach(k=>saved[k]===undefined?delete process.env[k]:process.env[k]=saved[k]);}
  fs.writeFileSync(portalRoot+'/.tmp/sails-retirement/final-review-r25/inherited-doi-results.json',JSON.stringify(results,null,2)+'\n');
  console.log(JSON.stringify({cases:results.length,baselineAndIncomingAgree:true}));
})().catch(e=>{console.error(e);process.exitCode=1});
